const weekStr = 'W' + Math.ceil((new Date().getDate()) / 7) + '_' + (new Date().getMonth() + 1);

return items.map(item => {
  const d = item.json;
  const token = Buffer.from((d.email || 'emp') + '_' + Date.now()).toString('base64').substring(0, 16);
  const host = 'http://192.168.2.123:3000';
  return {
    json: {
