const totalResponses = 42;
const promoters = 28;
const passives = 9;
const detractors = 5;

const enpsScore = Math.round(((promoters - detractors) / totalResponses) * 100);
const responseRate = Math.round((totalResponses / totalEmployees) * 100);

return {
  totalEmployees,
  totalResponses,
  responseRate: responseRate + '%',
  promoters,
  detractors,
  enpsScore,
  healthStatus: enpsScore >= 40 ? 'XUẤT SẮC' : (enpsScore >= 20 ? 'TỐT' : 'CẦN CHÚ Ý'),
  calculatedAt: new Date().toISOString()
};

